    if(type==='release')html=modalFrame('Create a new release',`<p class="muted">Una release identifica una versión lista para compartir. Esta etiqueta será ficticia.</p><form id="release-form"><div class="form-group"><label for="release-tag">Tag *</label><input type="text" id="release-tag" name="tag" required placeholder="v1.0.0" pattern="[a-zA-Z0-9._-]+" maxlength="40"></div><div class="form-group"><label for="release-title">Release title *</label><input type="text" id="release-title" name="title" required placeholder="Mi primera versión" maxlength="120"></div><div id="release-error" class="field-error" role="alert"></div><button class="btn btn-primary" type="submit">Publish practice release</button></form>`);
